<?php require_login();$uid=$_SESSION['user']['id'];$st=$pdo->prepare("SELECT a.*,c.name college FROM admissions a LEFT JOIN colleges c ON c.id=a.college_id WHERE student_id=? ORDER BY a.id DESC");$st->execute([$uid]);$rows=$st->fetchAll(PDO::FETCH_ASSOC);?><section class="wrap section"><span class="eyebrow">STUDENT PORTAL</span><h1>Welcome, <?=h($_SESSION['user']['name'])?></h1><div class="stats"><div><b><?=count($rows)?></b><span>My records</span></div><div><b><?=count(array_filter($rows,fn($r)=>$r['mode']==='Distance'))?></b><span>Distance applications</span></div><div><b><?=count(array_filter($rows,fn($r)=>$r['status']==='Admitted'))?></b><span>Admissions</span></div></div><div class="section-head"><h2>My applications & admission records</h2><a class="btn btn-primary" href="<?=url('admission')?>">New enquiry</a></div><div class="table-wrap"><table><tr><th>Course</th><th>Institution</th><th>Mode</th><th>Session</th><th>Status</th></tr><?php foreach($rows as $r):?><tr><td><?=h($r['course'])?></td><td><?=h($r['college']??'Not selected')?></td><td><?=h($r['mode'])?></td><td><?=h($r['session'])?></td><td><span class="tag"><?=h($r['status'])?></span></td></tr><?php endforeach;?></table><?php if(!$rows):?><p>No admission records yet.</p><?php endif;?></div></section>